/**
 * Denormalised search index kept in step by `SearchService`.
 */
import { and, count, desc, eq, inArray, like, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { comments, getDb, issues, projects, searchIndex } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchIndexRow } from "@/server/db/schema/webhooks";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";

/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent.
 */
export async function upsertSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
  content: string,
  projectId: ProjectId | null,
): Promise<void> {
  const db = getDb();
  const indexedAt = toIsoTimestamp(new Date());

  const existing = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .get();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    return;
  }

  db.insert(searchIndex)
    .values({
      id: newId(),
      orgId,
      subjectKind,
      subjectId,
      projectId,
      content,
      indexedAt,
    })
    .run();
}

export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/** Remove descendants by their source relationships, including legacy index rows. */
export async function deleteIssueSearchDocuments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const db = getDb();
  const commentIds = db
    .select({ id: comments.id })
    .from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)));

  db.delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        or(
          and(eq(searchIndex.subjectKind, "issue"), eq(searchIndex.subjectId, issueId)),
          and(eq(searchIndex.subjectKind, "comment"), inArray(searchIndex.subjectId, commentIds)),
        ),
      ),
    )
    .run();
}

export async function deleteProjectSearchDocuments(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const db = getDb();
  const issueIds = db
    .select({ id: issues.id })
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)));
  const commentIds = db
    .select({ id: comments.id })
    .from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, issueIds)));

  db.delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        or(
          and(eq(searchIndex.subjectKind, "project"), eq(searchIndex.subjectId, projectId)),
          and(eq(searchIndex.subjectKind, "issue"), inArray(searchIndex.subjectId, issueIds)),
          and(eq(searchIndex.subjectKind, "comment"), inArray(searchIndex.subjectId, commentIds)),
        ),
      ),
    )
    .run();
}

/** A rebuild replaces one tenant's index, including stale or orphaned documents. */
export async function clearSearchDocuments(orgId: OrgId): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .run();
}

/**
 * Substring match over the denormalised content column. Deliberately simple —
 * source-row liveness is checked for both the page and its total, even when
 * stale documents remain from an earlier write or indexer failure.
 */
export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const liveProjects = db
    .select({ id: projects.id })
    .from(projects)
    .where(and(orgPredicate(projects.orgId, input.orgId), livePredicate(projects.archivedAt, {})));
  const liveIssues = db
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, input.orgId),
        livePredicate(issues.archivedAt, {}),
        inArray(issues.projectId, liveProjects),
      ),
    );
  const liveComments = db
    .select({ id: comments.id })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        livePredicate(comments.archivedAt, {}),
        inArray(comments.issueId, liveIssues),
      ),
    );

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    or(
      and(eq(searchIndex.subjectKind, "project"), inArray(searchIndex.subjectId, liveProjects)),
      and(eq(searchIndex.subjectKind, "issue"), inArray(searchIndex.subjectId, liveIssues)),
      and(eq(searchIndex.subjectKind, "comment"), inArray(searchIndex.subjectId, liveComments)),
    ),
    like(searchIndex.content, `%${input.q}%`),
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(searchIndex)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => row,
    (row) => ({ id: row.id, sortValue: row.indexedAt }),
  );
}

/** Drift alarm input: how many documents this org currently has indexed. */
export async function countIndexed(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export type SearchSubjectKind = 'issue' | 'comment' | 'project';

